#' Panel Structure Check
#'
#' Checks a panel before estimation (balance, duplicates, gaps, missing 
#' values, absorbing treatment, cohorts) and plots treatment status by unit 
#' and period.
#'
#' @examples
#' \donttest{
#' # d is a data frame with one row per unit and period
#' didsetup(data = d, id = 'id', time = 'year', treat = 'D')
#'}
#' @param data .
#' @param dep a string naming the outcome variable in \code{data}
#' @param id a string naming the unit identifier variable in \code{data}
#' @param time a string naming the period variable in \code{data}; values must
#'   be integers (a year or a period number)
#' @param treat a string naming the treatment variable in \code{data}: a 0/1
#'   indicator that never turns off, or the first treated period (see
#'   \code{treatType})
#' @param treatType \code{'indicator'} (default) if \code{treat} is a 0/1
#'   treatment indicator, or \code{'cohort'} if it holds the first treated
#'   period (0 or missing = never treated)
#' @param plotPalette \code{'color'} (default, colour-blind safe) or
#'   \code{'gray'} (shades, shapes and line types for printing)
#' @param showHelp \code{TRUE} or \code{FALSE} (default), show notes on what
#'   the method does and how to read the results
#' @param showGuide \code{TRUE} or \code{FALSE} (default), show a guide to the
#'   variables and the data format
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$info} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$checks} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cohorts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$checks$asDF}
#'
#' \code{as.data.frame(results$checks)}
#'
#' @export
didsetup <- function(
    data,
    dep = NULL,
    id,
    time,
    treat,
    treatType = "indicator",
    plotPalette = "color",
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("didsetup requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(id)) id <- jmvcore::resolveQuo(jmvcore::enquo(id))
    if ( ! missing(time)) time <- jmvcore::resolveQuo(jmvcore::enquo(time))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(id), id, NULL),
            `if`( ! missing(time), time, NULL),
            `if`( ! missing(treat), treat, NULL))


    options <- didsetupOptions$new(
        dep = dep,
        id = id,
        time = time,
        treat = treat,
        treatType = treatType,
        plotPalette = plotPalette,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- didsetupClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

